{
  "name": "Nocturne Music & Lyrics",
  "description": "A dark-themed local music player that uses AI to generate synchronized lyrics in your preferred language."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Song {
  id: string;
  file: File;
  name: string;
  duration?: number;
  url: string;
}

export interface LyricLine {
  time: number; // in seconds
  text: string;
}

export interface LyricsData {
  language: string;
  lines: LyricLine[];
  plainText?: string; // Fallback if timestamping fails
}

export enum LyricsStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR',
}

export const LANGUAGES = [
  "English",
  "Spanish",
  "French",
  "German",
  "Japanese",
  "Korean",
  "Chinese",
  "Hindi",
  "Portuguese",
  "Russian",
  "Italian"
];

import { GoogleGenAI } from "@google/genai";
import { LyricLine, LyricsData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper to convert file to base64
const fileToGenerativePart = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g. "data:audio/mp3;base64,")
      const base64Content = base64String.split(',')[1];
      resolve(base64Content);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const generateLyrics = async (audioFile: File, language: string): Promise<LyricsData> => {
  try {
    const audioBase64 = await fileToGenerativePart(audioFile);

    const prompt = `
      Listen to the attached audio file. 
      Task: Transcribe the lyrics of the song in ${language}.

      Format requirements:
      1. Return the lyrics in LRC format (Time-synchronized lyrics).
      2. Format: [mm:ss.xx] Lyric text
      3. If the song is instrumental, return "[00:00.00] (Instrumental)".
      4. Ensure the timestamps are accurate to the audio.
      5. Do not include any conversational filler, markdown formatting blocks (like \`\`\`), or introductory text. Just the raw LRC content.
      6. If you cannot determine exact timestamps, just provide the plain text lyrics line by line.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: audioFile.type || 'audio/mp3',
              data: audioBase64
            }
          },
          { text: prompt }
        ]
      }
    });

    const text = response.text || '';
    return parseLyrics(text, language);

  } catch (error) {
    console.error("Gemini Lyrics Error:", error);
    throw error;
  }
};

const parseLyrics = (rawText: string, language: string): LyricsData => {
  const lines: LyricLine[] = [];
  const rawLines = rawText.split('\n');
  const timeRegex = /\[(\d{2}):(\d{2})\.(\d{2,3})\](.*)/;

  // Clean up potential markdown code blocks if the model ignored instructions
  const cleanLines = rawLines.filter(line => !line.startsWith('```'));

  let hasTimestamps = false;

  for (const line of cleanLines) {
    const match = line.match(timeRegex);
    if (match) {
      hasTimestamps = true;
      const minutes = parseInt(match[1], 10);
      const seconds = parseInt(match[2], 10);
      const milliseconds = parseInt(match[3].padEnd(3, '0'), 10); // Ensure 3 digits
      const content = match[4].trim();

      const totalSeconds = minutes * 60 + seconds + milliseconds / 1000;

      if (content) {
        lines.push({
          time: totalSeconds,
          text: content
        });
      }
    } else if (line.trim().length > 0) {
      // Fallback for lines without timestamps if mixed, 
      // or if the model failed timestamps completely, we capture text.
      // We assign a dummy time or -1 to indicate no sync.
      lines.push({
        time: -1, 
        text: line.trim()
      });
    }
  }

  // If we didn't find good timestamps, treat it as plain text
  if (!hasTimestamps) {
    return {
      language,
      lines: [],
      plainText: rawText
    };
  }

  return {
    language,
    lines,
  };
};

import React, { useRef } from 'react';
import { Song } from '../types';
import { FolderOpen, Music, Play } from 'lucide-react';

interface LibraryProps {
  songs: Song[];
  currentSong: Song | null;
  onSongSelect: (song: Song) => void;
  onFilesSelected: (files: FileList) => void;
}

const Library: React.FC<LibraryProps> = ({ songs, currentSong, onSongSelect, onFilesSelected }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFilesSelected(e.target.files);
    }
  };

  const handleOpenFolder = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 backdrop-blur-sm border-r border-slate-800">
      <div className="p-4 border-b border-slate-800 flex items-center justify-between">
        <h2 className="text-sm font-semibold text-slate-400 tracking-wider uppercase">Library</h2>
        <button 
          onClick={handleOpenFolder}
          className="p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-colors flex items-center gap-2 text-xs font-bold"
        >
          <FolderOpen size={14} />
          <span>SCAN LOCAL</span>
        </button>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          className="hidden"
          // @ts-ignore - webkitdirectory is standard in modern browsers for folder selection but not in TS definition by default
          webkitdirectory=""
          multiple
          accept="audio/*"
        />
      </div>

      <div className="flex-1 overflow-y-auto">
        {songs.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-slate-500 gap-3 p-8 text-center">
            <Music size={48} className="opacity-20" />
            <p className="text-sm">No music found.</p>
            <p className="text-xs">Click "Scan Local" to load a folder of music from your Windows PC.</p>
          </div>
        ) : (
          <ul className="divide-y divide-slate-800/50">
            {songs.map((song) => (
              <li 
                key={song.id}
                onClick={() => onSongSelect(song)}
                className={`group flex items-center gap-3 p-3 cursor-pointer transition-all hover:bg-white/5 ${
                  currentSong?.id === song.id ? 'bg-indigo-900/20 border-l-2 border-indigo-500' : 'border-l-2 border-transparent'
                }`}
              >
                <div className={`p-2 rounded-md ${currentSong?.id === song.id ? 'text-indigo-400' : 'text-slate-500 group-hover:text-slate-300'}`}>
                  {currentSong?.id === song.id ? <Play size={16} fill="currentColor" /> : <Music size={16} />}
                </div>
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-medium truncate ${currentSong?.id === song.id ? 'text-indigo-200' : 'text-slate-300'}`}>
                    {song.name}
                  </p>
                  <p className="text-xs text-slate-500 truncate">Local File</p>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default Library;

import React, { useEffect, useRef, useState } from 'react';
import { Song } from '../types';
import { Play, Pause, SkipBack, SkipForward, Volume2, Repeat } from 'lucide-react';

interface PlayerProps {
  currentSong: Song | null;
  onNext: () => void;
  onPrev: () => void;
  onTimeUpdate: (currentTime: number) => void;
}

const Player: React.FC<PlayerProps> = ({ currentSong, onNext, onPrev, onTimeUpdate }) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.7);

  useEffect(() => {
    if (currentSong && audioRef.current) {
      audioRef.current.src = currentSong.url;
      audioRef.current.play()
        .then(() => setIsPlaying(true))
        .catch(e => console.error("Playback error", e));
    }
  }, [currentSong]);

  const togglePlay = () => {
    if (!audioRef.current || !currentSong) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const current = audioRef.current.currentTime;
      const dur = audioRef.current.duration;
      setProgress(current);
      setDuration(dur || 0);
      onTimeUpdate(current);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (audioRef.current) {
      const time = Number(e.target.value);
      audioRef.current.currentTime = time;
      setProgress(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = Number(e.target.value);
    setVolume(vol);
    if (audioRef.current) {
      audioRef.current.volume = vol;
    }
  };

  const formatTime = (time: number) => {
    if (!time || isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 p-6 flex-shrink-0 w-96 border-r border-slate-800">
      {/* Album Art Area */}
      <div className="aspect-square w-full bg-slate-800 rounded-2xl mb-8 shadow-2xl shadow-indigo-500/10 overflow-hidden relative group">
        {currentSong ? (
          <img 
            src="https://picsum.photos/400/400?grayscale" 
            alt="Album Art" 
            className={`w-full h-full object-cover transition-transform duration-700 ${isPlaying ? 'scale-105' : 'scale-100'}`}
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-slate-600">
            <Music size={64} />
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent opacity-60"></div>
      </div>

      {/* Song Info */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-white mb-2 truncate leading-tight">
          {currentSong ? currentSong.name : "No Song Selected"}
        </h1>
        <p className="text-slate-400 text-sm font-medium">Local Library</p>
      </div>

      {/* Controls */}
      <div className="mt-auto space-y-6">
        {/* Progress Bar */}
        <div className="space-y-2">
          <input
            type="range"
            min={0}
            max={duration || 100}
            value={progress}
            onChange={handleSeek}
            disabled={!currentSong}
            className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-indigo-500"
          />
          <div className="flex justify-between text-xs text-slate-500 font-mono">
            <span>{formatTime(progress)}</span>
            <span>{formatTime(duration)}</span>
          </div>
        </div>

        {/* Main Buttons */}
        <div className="flex items-center justify-between px-2">
          <button className="text-slate-400 hover:text-white transition-colors" disabled={!currentSong}>
             <Repeat size={20} />
          </button>
          <button onClick={onPrev} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
            <SkipBack size={28} />
          </button>
          <button 
            onClick={togglePlay}
            disabled={!currentSong}
            className="w-14 h-14 bg-indigo-500 hover:bg-indigo-400 rounded-full flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
          </button>
          <button onClick={onNext} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
            <SkipForward size={28} />
          </button>

          <div className="relative group flex items-center">
             <Volume2 size={20} className="text-slate-400 group-hover:text-white" />
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 hidden group-hover:block p-2 bg-slate-800 rounded-lg shadow-xl mb-2">
                <input 
                  type="range" 
                  min="0" max="1" step="0.01" 
                  value={volume} 
                  onChange={handleVolumeChange}
                  className="h-24 -rotate-90 origin-center w-8 bg-transparent"
                />
             </div>
          </div>
        </div>
      </div>

      <audio 
        ref={audioRef}
        onTimeUpdate={handleTimeUpdate}
        onEnded={onNext}
      />
    </div>
  );
};

export default Player;

import React, { useEffect, useRef, useState } from 'react';
import { LANGUAGES, LyricLine, LyricsData, LyricsStatus, Song } from '../types';
import { generateLyrics } from '../services/geminiService';
import { Sparkles, AlertCircle, Mic2 } from 'lucide-react';

interface LyricsDisplayProps {
  currentSong: Song | null;
  currentTime: number;
}

const LyricsDisplay: React.FC<LyricsDisplayProps> = ({ currentSong, currentTime }) => {
  const [status, setStatus] = useState<LyricsStatus>(LyricsStatus.IDLE);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0]);
  const [errorMsg, setErrorMsg] = useState("");

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const activeLineRef = useRef<HTMLDivElement>(null);

  // Reset state when song changes
  useEffect(() => {
    setStatus(LyricsStatus.IDLE);
    setLyricsData(null);
    setErrorMsg("");
  }, [currentSong]);

  // Handle auto-scroll based on time
  useEffect(() => {
    if (activeLineRef.current && scrollContainerRef.current) {
      activeLineRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'center'
      });
    }
  }, [currentTime, lyricsData]);

  const handleGenerate = async () => {
    if (!currentSong) return;

    setStatus(LyricsStatus.LOADING);
    setErrorMsg("");

    try {
      const data = await generateLyrics(currentSong.file, selectedLanguage);
      setLyricsData(data);
      setStatus(LyricsStatus.SUCCESS);
    } catch (err) {
      setStatus(LyricsStatus.ERROR);
      setErrorMsg("Failed to generate lyrics. Please try again or check your API key.");
    }
  };

  // Logic to find active line
  const getActiveLineIndex = () => {
    if (!lyricsData || !lyricsData.lines || lyricsData.lines.length === 0) return -1;
    // Find the last line that has a time less than current time
    for (let i = lyricsData.lines.length - 1; i >= 0; i--) {
      if (lyricsData.lines[i].time <= currentTime) {
        return i;
      }
    }
    return -1;
  };

  const activeIndex = getActiveLineIndex();

  if (!currentSong) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center bg-slate-950 p-8 border-l border-slate-800">
        <Mic2 className="w-16 h-16 text-slate-800 mb-4" />
        <h2 className="text-xl font-bold text-slate-700">Lyrics Area</h2>
        <p className="text-slate-600 mt-2">Play a song to get started</p>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-950 relative border-l border-slate-800">
      {/* Header / Toolbar */}
      <div className="p-6 flex items-center justify-between bg-slate-950/80 backdrop-blur-sm z-10 border-b border-slate-900 sticky top-0">
        <div className="flex items-center gap-2">
            <h2 className="text-xl font-bold text-white tracking-tight">Lyrics AI</h2>
            {status === LyricsStatus.SUCCESS && (
                <span className="px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-400 text-xs font-medium border border-indigo-500/20">
                    {lyricsData?.language}
                </span>
            )}
        </div>

        {status === LyricsStatus.IDLE || status === LyricsStatus.ERROR ? (
          <div className="flex items-center gap-3">
            <select
              value={selectedLanguage}
              onChange={(e) => setSelectedLanguage(e.target.value)}
              className="bg-slate-900 text-slate-300 text-sm rounded-lg border border-slate-700 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 px-3 py-2 outline-none"
            >
              {LANGUAGES.map(lang => (
                <option key={lang} value={lang}>{lang}</option>
              ))}
            </select>
            <button
              onClick={handleGenerate}
              className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-lg text-sm font-semibold transition-all shadow-lg shadow-indigo-500/20"
            >
              <Sparkles size={16} />
              Generate
            </button>
          </div>
        ) : status === LyricsStatus.LOADING ? (
          <div className="flex items-center gap-2 text-indigo-400 text-sm animate-pulse">
            <Sparkles size={16} />
            <span>Analyzing audio stream...</span>
          </div>
        ) : (
            // Option to regenerate
             <button
              onClick={() => setStatus(LyricsStatus.IDLE)}
              className="text-xs text-slate-500 hover:text-slate-300 underline"
            >
              Change Language
            </button>
        )}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto relative p-8" ref={scrollContainerRef}>

        {status === LyricsStatus.ERROR && (
          <div className="flex flex-col items-center justify-center h-full text-red-400 space-y-2">
            <AlertCircle size={32} />
            <p>{errorMsg}</p>
          </div>
        )}

        {status === LyricsStatus.IDLE && (
          <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4">
             <div className="w-16 h-16 rounded-full bg-slate-900 flex items-center justify-center mb-2">
                <Sparkles size={24} className="text-indigo-500" />
             </div>
             <p className="max-w-md text-center">
                Click "Generate" to use Gemini AI to listen to this song and transcribe lyrics in real-time.
             </p>
          </div>
        )}

        {status === LyricsStatus.SUCCESS && lyricsData && (
          <div className="space-y-8 pb-32 pt-10 text-center">
            {lyricsData.lines.length > 0 ? (
                lyricsData.lines.map((line, index) => {
                  const isActive = index === activeIndex;
                  return (
                    <div
                      key={index}
                      ref={isActive ? activeLineRef : null}
                      className={`transition-all duration-500 ease-out transform ${
                        isActive 
                          ? 'text-white text-3xl font-bold scale-100 opacity-100 my-8 blur-none' 
                          : 'text-slate-600 text-xl font-medium scale-95 opacity-40 blur-[1px]'
                      }`}
                    >
                      <p>{line.text}</p>
                    </div>
                  );
                })
            ) : (
                // Fallback for plain text
                <div className="text-slate-300 whitespace-pre-wrap leading-loose text-lg font-medium">
                    {lyricsData.plainText}
                </div>
            )}

            {/* Footer space */}
            <div className="h-32"></div>
          </div>
        )}
      </div>
    </div>
  );
};

export default LyricsDisplay;

import React, { useState } from 'react';
import Library from './components/Library';
import Player from './components/Player';
import LyricsDisplay from './components/LyricsDisplay';
import { Song } from './types';

const App: React.FC = () => {
  const [songs, setSongs] = useState<Song[]>([]);
  const [currentSong, setCurrentSong] = useState<Song | null>(null);
  const [currentTime, setCurrentTime] = useState(0);

  const handleFilesSelected = (fileList: FileList) => {
    const newSongs: Song[] = [];
    Array.from(fileList).forEach((file) => {
      // Basic check for audio files
      if (file.type.startsWith('audio/') || file.name.endsWith('.mp3') || file.name.endsWith('.wav')) {
        newSongs.push({
          id: `${file.name}-${Date.now()}-${Math.random()}`,
          name: file.name.replace(/\.[^/.]+$/, ""), // remove extension
          file: file,
          url: URL.createObjectURL(file)
        });
      }
    });
    setSongs(prev => [...prev, ...newSongs]);
  };

  const handleSongSelect = (song: Song) => {
    setCurrentSong(song);
  };

  const handleNext = () => {
    if (!currentSong || songs.length === 0) return;
    const currentIndex = songs.findIndex(s => s.id === currentSong.id);
    const nextIndex = (currentIndex + 1) % songs.length;
    setCurrentSong(songs[nextIndex]);
  };

  const handlePrev = () => {
    if (!currentSong || songs.length === 0) return;
    const currentIndex = songs.findIndex(s => s.id === currentSong.id);
    const prevIndex = (currentIndex - 1 + songs.length) % songs.length;
    setCurrentSong(songs[prevIndex]);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
      {/* Left Sidebar: Player and Library */}
      <div className="flex flex-col w-[450px] h-full border-r border-slate-800 shadow-2xl z-20">
        <div className="h-[60%] border-b border-slate-800">
            <Player 
                currentSong={currentSong} 
                onNext={handleNext} 
                onPrev={handlePrev}
                onTimeUpdate={setCurrentTime}
            />
        </div>
        <div className="h-[40%] bg-slate-900">
            <Library 
                songs={songs} 
                currentSong={currentSong} 
                onSongSelect={handleSongSelect}
                onFilesSelected={handleFilesSelected}
            />
        </div>
      </div>

      {/* Right Content: Lyrics */}
      <main className="flex-1 h-full min-w-0">
        <LyricsDisplay currentSong={currentSong} currentTime={currentTime} />
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Song } from '../types';
import { Play, Pause, SkipBack, SkipForward, Volume2, Repeat, Music } from 'lucide-react';

interface PlayerProps {
  currentSong: Song | null;
  onNext: () => void;
  onPrev: () => void;
  onTimeUpdate: (currentTime: number) => void;
}

const Player: React.FC<PlayerProps> = ({ currentSong, onNext, onPrev, onTimeUpdate }) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.7);

  useEffect(() => {
    if (currentSong && audioRef.current) {
      audioRef.current.src = currentSong.url;
      audioRef.current.play()
        .then(() => setIsPlaying(true))
        .catch(e => console.error("Playback error", e));
    }
  }, [currentSong]);

  const togglePlay = () => {
    if (!audioRef.current || !currentSong) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const current = audioRef.current.currentTime;
      const dur = audioRef.current.duration;
      setProgress(current);
      setDuration(dur || 0);
      onTimeUpdate(current);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (audioRef.current) {
      const time = Number(e.target.value);
      audioRef.current.currentTime = time;
      setProgress(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = Number(e.target.value);
    setVolume(vol);
    if (audioRef.current) {
      audioRef.current.volume = vol;
    }
  };

  const formatTime = (time: number) => {
    if (!time || isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
