          <button onClick={onPrev} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
            <SkipBack size={28} />
          </button>
          <button 
            onClick={togglePlay}
            disabled={!currentSong}
            className="w-14 h-14 bg-indigo-500 hover:bg-indigo-400 rounded-full flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
          </button>
          <button onClick={onNext} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
            <SkipForward size={28} />
