      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentSong]);

  // Cleanup on unmount
  useEffect(() => {
      return () => {
          if (requestRef.current) cancelAnimationFrame(requestRef.current);
          if (audioContextRef.current) audioContextRef.current.close();
      };
  }, []);

  // Sync props state to audio element
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.playbackRate = speed;
      audioRef.current.volume = volume;
    }
  }, [speed, volume]);

  const togglePlay = () => {
    if (!audioRef.current || !currentSong) return;

    // Resume context if suspended (needed for some browsers)
    if (audioContextRef.current?.state === 'suspended') {
        audioContextRef.current.resume();
    }

    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const current = audioRef.current.currentTime;
      const dur = audioRef.current.duration;
      setProgress(current);
      setDuration(dur || 0);
      onTimeUpdate(current);
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (audioRef.current) {
      const time = Number(e.target.value);
      audioRef.current.currentTime = time;
      setProgress(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const vol = Number(e.target.value);
    setVolume(vol);
    if (vol > 0) {
        setPrevVolume(vol);
    }
  };

  const toggleMute = () => {
    if (volume > 0) {
        setPrevVolume(volume);
        setVolume(0);
    } else {
        setVolume(prevVolume > 0 ? prevVolume : 0.5);
    }
  };

  const cycleSpeed = () => {
    const speeds = [0.5, 1, 1.5, 2];
    const nextIndex = (speeds.indexOf(speed) + 1) % speeds.length;
    setSpeed(speeds[nextIndex]);
  };

  const formatTime = (time: number) => {
    if (!time || isNaN(time)) return "0:00";
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 p-6 flex-shrink-0 w-full border-r border-slate-800">
      {/* Album Art Area with Visualizer */}
      <div className="aspect-square w-full bg-slate-900 rounded-2xl mb-8 shadow-2xl shadow-indigo-500/10 relative flex items-center justify-center group overflow-hidden">
        {/* Visualizer Canvas - Behind the image */}
        <canvas 
            ref={canvasRef} 
            width={400} 
            height={400} 
            className="absolute inset-0 w-full h-full opacity-60 z-0 pointer-events-none"
        />

        {/* Album Image - On top */}
        <div className="relative z-10 w-[85%] h-[85%] rounded-full overflow-hidden shadow-2xl border-4 border-slate-800/50">
             {currentSong ? (
            <img 
                src="https://picsum.photos/400/400?grayscale" 
                alt="Album Art" 
                className={`w-full h-full object-cover transition-transform duration-[3s] ease-linear ${isPlaying ? 'rotate-[360deg] animate-[spin_10s_linear_infinite]' : ''}`}
            />
            ) : (
            <div className="w-full h-full flex items-center justify-center bg-slate-800 text-slate-600">
                <Music size={64} />
            </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500/20 to-transparent pointer-events-none"></div>
        </div>
      </div>

      {/* Song Info */}
      <div className="mb-8 text-center">
        <h1 className="text-2xl font-bold text-white mb-2 truncate leading-tight">
          {currentSong ? currentSong.name : "No Song Selected"}
        </h1>
        <p className="text-slate-400 text-sm font-medium">Local Library</p>
      </div>

      {/* Controls */}
      <div className="mt-auto space-y-6">
        {/* Progress Bar */}
        <div className="space-y-2">
          <input
            type="range"
            min={0}
            max={duration || 100}
            value={progress}
            onChange={handleSeek}
            disabled={!currentSong}
            className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-indigo-500 hover:[&::-webkit-slider-thumb]:scale-125 transition-all"
          />
          <div className="flex justify-between text-xs text-slate-500 font-mono">
            <span>{formatTime(progress)}</span>
            <span>{formatTime(duration)}</span>
          </div>
        </div>

        {/* Main Buttons */}
        <div className="flex items-center justify-between gap-2">
          {/* Speed, Repeat, Lyrics */}
          <div className="flex items-center gap-2">
             <button 
                onClick={cycleSpeed} 
                className="text-slate-400 hover:text-white transition-colors text-xs font-bold w-6 flex items-center justify-center" 
                title="Playback Speed"
                disabled={!currentSong}
              >
                {speed}x
              </button>
              <button className="text-slate-400 hover:text-white transition-colors" disabled={!currentSong}>
                 <Repeat size={18} />
              </button>
              <button 
                onClick={onToggleLyrics}
                className={`transition-colors ${isLyricsOpen ? 'text-indigo-400' : 'text-slate-400 hover:text-white'}`}
                disabled={!currentSong}
                title="Toggle AI Lyrics"
              >
                 <Mic2 size={18} />
              </button>
          </div>

          {/* Playback Controls */}
          <div className="flex items-center gap-4">
            <button onClick={onPrev} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
                <SkipBack size={24} />
            </button>
            <button 
                onClick={togglePlay}
                disabled={!currentSong}
                className="w-12 h-12 bg-indigo-500 hover:bg-indigo-400 rounded-full flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
            >
                {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-1" />}
            </button>
            <button onClick={onNext} className="text-slate-300 hover:text-white transition-colors" disabled={!currentSong}>
                <SkipForward size={24} />
            </button>
          </div>

          {/* Volume Control */}
          <div className="flex items-center gap-2 group">
             <button onClick={toggleMute} className="text-slate-400 hover:text-white transition-colors" disabled={!currentSong}>
                {volume === 0 ? <VolumeX size={18} /> : <Volume2 size={18} />}
             </button>
             <input 
                type="range" 
                min="0" max="1" step="0.05" 
                value={volume} 
                onChange={handleVolumeChange}
                disabled={!currentSong}
                className="w-16 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-2.5 [&::-webkit-slider-thumb]:h-2.5 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-slate-400 hover:[&::-webkit-slider-thumb]:bg-white"
                title={`Volume: ${Math.round(volume * 100)}%`}
             />
          </div>
        </div>
      </div>

      <audio 
        ref={audioRef}
        onTimeUpdate={handleTimeUpdate}
        onEnded={onNext}
        crossOrigin="anonymous"
      />
    </div>
  );
};

export default Player;

import React, { useState } from 'react';
import Library from './components/Library';
import Player from './components/Player';
import LyricsDisplay from './components/LyricsDisplay';
import { Song } from './types';

const App: React.FC = () => {
  const [songs, setSongs] = useState<Song[]>([]);
  const [currentSong, setCurrentSong] = useState<Song | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [isLyricsOpen, setIsLyricsOpen] = useState(false);

  const handleFilesSelected = (fileList: FileList) => {
    const newSongs: Song[] = [];
    const validExtensions = ['.mp3', '.wav', '.ogg', '.flac', '.m4a', '.aac'];

    Array.from(fileList).forEach((file) => {
      const isAudioType = file.type.startsWith('audio/');
      const hasValidExtension = validExtensions.some(ext => file.name.toLowerCase().endsWith(ext));

      if (isAudioType || hasValidExtension) {
        newSongs.push({
          id: `${file.name}-${Date.now()}-${Math.random()}`,
          name: file.name.replace(/\.[^/.]+$/, ""), // remove extension
          file: file,
          url: URL.createObjectURL(file)
        });
      }
    });
    setSongs(prev => [...prev, ...newSongs]);
  };

  const handleSongSelect = (song: Song) => {
    setCurrentSong(song);
  };

  const handleNext = () => {
    if (!currentSong || songs.length === 0) return;
    const currentIndex = songs.findIndex(s => s.id === currentSong.id);
    const nextIndex = (currentIndex + 1) % songs.length;
    setCurrentSong(songs[nextIndex]);
  };

  const handlePrev = () => {
    if (!currentSong || songs.length === 0) return;
    const currentIndex = songs.findIndex(s => s.id === currentSong.id);
    const prevIndex = (currentIndex - 1 + songs.length) % songs.length;
    setCurrentSong(songs[prevIndex]);
  };

  return (
    <div className="flex h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans relative">
       {/* Ambient Background for centered mode */}
       {!isLyricsOpen && (
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-950/30 via-slate-950 to-slate-950 pointer-events-none z-0"></div>
       )}

      {/* Main Player/Library Container */}
      <div className={`flex flex-col h-full bg-slate-950 transition-all duration-500 ease-[cubic-bezier(0.25,1,0.5,1)] z-20 shadow-2xl relative
        ${isLyricsOpen ? 'w-[450px] border-r border-slate-800' : 'w-full max-w-4xl mx-auto border-x border-slate-800'}`}>

        <div className="h-[60%] border-b border-slate-800">
            <Player 
                currentSong={currentSong} 
                onNext={handleNext} 
                onPrev={handlePrev}
                onTimeUpdate={setCurrentTime}
                isLyricsOpen={isLyricsOpen}
                onToggleLyrics={() => setIsLyricsOpen(!isLyricsOpen)}
            />
        </div>
        <div className="h-[40%] bg-slate-900/50 backdrop-blur-md">
            <Library 
                songs={songs} 
                currentSong={currentSong} 
                onSongSelect={handleSongSelect}
                onFilesSelected={handleFilesSelected}
            />
        </div>
      </div>

      {/* Lyrics Content - Hidden via display:none logic to preserve state if needed, or conditional rendering. 
          Using 'hidden' class keeps it mounted but invisible, good for toggling.
      */}
      <main className={`flex-1 h-full min-w-0 transition-opacity duration-500 ease-in-out ${isLyricsOpen ? 'opacity-100 block' : 'opacity-0 hidden'}`}>
        <LyricsDisplay currentSong={currentSong} currentTime={currentTime} />
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { LANGUAGES, LyricLine, LyricsData, LyricsStatus, Song } from '../types';
import { generateLyrics } from '../services/geminiService';
import { Sparkles, AlertCircle, Mic2, Languages, Edit3, Save, Clock, Plus, Minus, RotateCcw } from 'lucide-react';

interface LyricsDisplayProps {
  currentSong: Song | null;
  currentTime: number;
}

const LyricsDisplay: React.FC<LyricsDisplayProps> = ({ currentSong, currentTime }) => {
  const [status, setStatus] = useState<LyricsStatus>(LyricsStatus.IDLE);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  // Default to the first language which is Auto-Detect
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0]);
  const [errorMsg, setErrorMsg] = useState("");
  const [isEditing, setIsEditing] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const activeLineRef = useRef<HTMLDivElement>(null);
  const currentSongIdRef = useRef<string>("");

  // Handle auto-scroll based on time
  useEffect(() => {
    if (!isEditing && activeLineRef.current && scrollContainerRef.current) {
      activeLineRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'center'
      });
    }
  }, [currentTime, lyricsData, isEditing]);

  const performGeneration = async (song: Song, lang: string) => {
    setStatus(LyricsStatus.LOADING);
    setErrorMsg("");
    setLyricsData(null);
    setIsEditing(false);

    try {
      const data = await generateLyrics(song.file, lang);

      // Prevent race conditions: only update if the song hasn't changed
      if (currentSongIdRef.current === song.id) {
        setLyricsData(data);
        setStatus(LyricsStatus.SUCCESS);
      }
    } catch (err: any) {
      if (currentSongIdRef.current === song.id) {
        setStatus(LyricsStatus.ERROR);
        setErrorMsg(err.message || "Failed to generate lyrics. Please try again.");
      }
    }
  };

  // Auto-generate on song change
  useEffect(() => {
    if (currentSong) {
        currentSongIdRef.current = currentSong.id;
        performGeneration(currentSong, selectedLanguage);
    } else {
        currentSongIdRef.current = "";
        setStatus(LyricsStatus.IDLE);
        setLyricsData(null);
        setErrorMsg("");
        setIsEditing(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentSong]);

  const handleManualGenerate = () => {
    if (currentSong) {
        performGeneration(currentSong, selectedLanguage);
    }
  };

  const toggleEditMode = () => {
    if (isEditing && lyricsData) {
        // Save mode: sort lines by time to ensure playback logic works
        const sortedLines = [...lyricsData.lines].sort((a, b) => a.time - b.time);
        setLyricsData({ ...lyricsData, lines: sortedLines });
    }
    setIsEditing(!isEditing);
  };

  const adjustTimestamp = (index: number, delta: number) => {
    if (!lyricsData) return;
    const newLines = [...lyricsData.lines];
    newLines[index].time = Math.max(0, newLines[index].time + delta);
    setLyricsData({ ...lyricsData, lines: newLines });
  };

  const syncToCurrentTime = (index: number) => {
    if (!lyricsData) return;
    const newLines = [...lyricsData.lines];
    newLines[index].time = currentTime;
    setLyricsData({ ...lyricsData, lines: newLines });
  };

  const updateLineText = (index: number, text: string) => {
    if (!lyricsData) return;
    const newLines = [...lyricsData.lines];
    newLines[index].text = text;
    setLyricsData({ ...lyricsData, lines: newLines });
  };

  const formatTimestamp = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 10); // 1 decimal place
    return `${mins}:${secs.toString().padStart(2, '0')}.${ms}`;
  };

  // Logic to find active line
  const getActiveLineIndex = () => {
    if (!lyricsData || !lyricsData.lines || lyricsData.lines.length === 0) return -1;
    // Find the last line that has a time less than current time
    for (let i = lyricsData.lines.length - 1; i >= 0; i--) {
      if (lyricsData.lines[i].time <= currentTime) {
        return i;
      }
    }
    return -1;
  };

  const activeIndex = getActiveLineIndex();

  if (!currentSong) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center bg-slate-950 p-8 border-l border-slate-800">
        <Mic2 className="w-16 h-16 text-slate-800 mb-4" />
        <h2 className="text-xl font-bold text-slate-700">Lyrics Area</h2>
        <p className="text-slate-600 mt-2">Play a song to get started</p>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-950 relative border-l border-slate-800">
      {/* Header / Toolbar */}
      <div className="p-6 flex items-center justify-between bg-slate-950/80 backdrop-blur-sm z-10 border-b border-slate-900 sticky top-0">
        <div className="flex items-center gap-2">
            <h2 className="text-xl font-bold text-white tracking-tight">Lyrics AI</h2>
            {status === LyricsStatus.SUCCESS && (
                <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-400 text-xs font-medium border border-indigo-500/20">
                    <Languages size={10} />
                    <span>{lyricsData?.language}</span>
                </div>
            )}
        </div>

        {status === LyricsStatus.IDLE || status === LyricsStatus.ERROR ? (
          <div className="flex items-center gap-3">
            <select
              value={selectedLanguage}
              onChange={(e) => setSelectedLanguage(e.target.value)}
              className="bg-slate-900 text-slate-300 text-sm rounded-lg border border-slate-700 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 px-3 py-2 outline-none"
            >
              {LANGUAGES.map(lang => (
                <option key={lang} value={lang}>{lang}</option>
              ))}
            </select>
            <button
              onClick={handleManualGenerate}
              className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-lg text-sm font-semibold transition-all shadow-lg shadow-indigo-500/20"
            >
              {status === LyricsStatus.ERROR ? <RotateCcw size={16} /> : <Sparkles size={16} />}
              {status === LyricsStatus.ERROR ? "Retry" : "Generate"}
            </button>
          </div>
        ) : status === LyricsStatus.LOADING ? (
          <div className="flex items-center gap-2 text-indigo-400 text-sm animate-pulse">
            <Sparkles size={16} />
            <span>Analyzing song...</span>
          </div>
        ) : (
            <div className="flex items-center gap-4">
                 <button
                    onClick={toggleEditMode}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-all ${
                        isEditing 
                        ? 'bg-green-600 hover:bg-green-500 text-white shadow-lg shadow-green-500/20' 
                        : 'bg-slate-800 hover:bg-slate-700 text-slate-300'
                    }`}
                >
                    {isEditing ? <Save size={14} /> : <Edit3 size={14} />}
                    {isEditing ? 'Save Sync' : 'Edit Sync'}
                </button>

                {!isEditing && (
                    <button
                        onClick={() => setStatus(LyricsStatus.IDLE)}
                        className="text-xs text-slate-500 hover:text-slate-300 underline"
                    >
                        Regenerate
                    </button>
                )}
            </div>
        )}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto relative p-8" ref={scrollContainerRef}>

        {status === LyricsStatus.ERROR && (
          <div className="flex flex-col items-center justify-center h-full text-red-400 space-y-2 p-4 text-center">
            <AlertCircle size={32} />
            <p className="max-w-md">{errorMsg}</p>
          </div>
        )}

        {status === LyricsStatus.IDLE && (
           /* IDLE state now implies waiting for song or manual retry */
          <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4">
             <div className="w-16 h-16 rounded-full bg-slate-900 flex items-center justify-center mb-2">
                <Sparkles size={24} className="text-indigo-500" />
             </div>
             <p className="max-w-md text-center">
                Ready to generate lyrics.
             </p>
          </div>
        )}

        {status === LyricsStatus.SUCCESS && lyricsData && (
          <div className={`${isEditing ? 'space-y-2 pb-10' : 'space-y-8 pb-32 pt-10 text-center'}`}>
            {lyricsData.lines.length > 0 ? (
                lyricsData.lines.map((line, index) => {
                  const isActive = index === activeIndex;

                  if (isEditing) {
                      return (
                        <div key={index} className="flex items-center gap-4 p-3 rounded-xl bg-slate-900/40 border border-slate-800 hover:border-indigo-500/30 group transition-all">
                             <div className="flex flex-col gap-1">
                                <span className="font-mono text-xs text-indigo-400 font-bold w-16 text-center bg-slate-950 py-1 rounded">
                                    {formatTimestamp(line.time)}
                                </span>
                             </div>

                             <div className="flex items-center gap-1 opacity-60 group-hover:opacity-100 transition-opacity">
                                <button onClick={() => adjustTimestamp(index, -0.5)} className="p-1.5 bg-slate-800 hover:bg-indigo-600 hover:text-white rounded text-slate-400 transition-colors" title="-0.5s">
                                    <Minus size={12} />
                                </button>
                                <button onClick={() => adjustTimestamp(index, 0.5)} className="p-1.5 bg-slate-800 hover:bg-indigo-600 hover:text-white rounded text-slate-400 transition-colors" title="+0.5s">
                                    <Plus size={12} />
                                </button>
                                <button onClick={() => syncToCurrentTime(index)} className="p-1.5 bg-slate-800 hover:bg-green-600 hover:text-white rounded text-slate-400 transition-colors ml-1" title="Sync to current player time">
                                    <Clock size={12} />
                                </button>
                             </div>

                             <input 
                                value={line.text}
                                onChange={(e) => updateLineText(index, e.target.value)}
                                className="flex-1 bg-transparent border-none outline-none text-slate-200 text-sm font-medium focus:text-white placeholder:text-slate-600"
                                placeholder="Lyric text..."
                             />
                        </div>
                      );
                  }

                  return (
                    <div
                      key={index}
                      ref={isActive ? activeLineRef : null}
                      className={`transition-all duration-500 ease-out transform cursor-default ${
                        isActive 
                          ? 'text-white text-3xl font-bold scale-100 opacity-100 my-8 blur-none' 
                          : 'text-slate-600 text-xl font-medium scale-95 opacity-40 blur-[1px] hover:opacity-60 hover:blur-none'
                      }`}
                    >
                      <p>{line.text}</p>
                    </div>
                  );
                })
            ) : (
                // Fallback for plain text
                <div className="text-slate-300 whitespace-pre-wrap leading-loose text-lg font-medium">
                    {lyricsData.plainText}
                </div>
            )}

            {/* Footer space */}
            {!isEditing && <div className="h-32"></div>}
          </div>
        )}
      </div>
    </div>
  );
};

export default LyricsDisplay;

import React, { useEffect, useRef, useState } from 'react';
import { Song } from '../types';
import { Play, Pause, SkipBack, SkipForward, Volume2, VolumeX, Repeat, Music, Mic2, ListMusic } from 'lucide-react';

interface PlayerProps {
  currentSong: Song | null;
  onNext: () => void;
  onPrev: () => void;
  onTimeUpdate: (currentTime: number) => void;
  isLyricsOpen: boolean;
  onToggleLyrics: () => void;
  isLibraryOpen: boolean;
  onToggleLibrary: () => void;
}

const Player: React.FC<PlayerProps> = ({ 
  currentSong, 
  onNext, 
  onPrev, 
  onTimeUpdate, 
  isLyricsOpen, 
  onToggleLyrics,
  isLibraryOpen,
  onToggleLibrary
}) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const requestRef = useRef<number>(0);

  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.7);
  const [prevVolume, setPrevVolume] = useState(0.7);
  const [speed, setSpeed] = useState(1);

  // Initialize Audio Context and Analyser (One time setup)
  const initAudioContext = () => {
    if (!audioContextRef.current && audioRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      const analyser = ctx.createAnalyser();

      // Higher fftSize = more detailed bars
      analyser.fftSize = 256; 

      const source = ctx.createMediaElementSource(audioRef.current);
      source.connect(analyser);
      analyser.connect(ctx.destination);

      audioContextRef.current = ctx;
      analyserRef.current = analyser;
      sourceRef.current = source;
    }
  };

  const drawVisualizer = () => {
    if (!canvasRef.current || !analyserRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyserRef.current.getByteFrequencyData(dataArray);

    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 2 - 20; // Leave some padding

    ctx.clearRect(0, 0, width, height);

    // Draw the circular visualizer
    ctx.beginPath();

    // Create a glow effect
    ctx.shadowBlur = 15;
    ctx.shadowColor = "rgba(99, 102, 241, 0.6)"; // Indigo glow

